from __future__ import absolute_import

import logging

from selenium.webdriver.common.by import By

from taf.selenium.gnb.oam.coam.cu.pages.common_page import CommonPage
from taf.selenium.gnb.oam.coam.cu.pages.panels.navigation import NavigationPanel
from taf.selenium.gnb.oam.coam.cu.pages.panels.view import ViewPanel


class BtsStatus(CommonPage):
    """
    The class corresponding to BTS status page on selenium coam cu webem, all operations under BTS status
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"DUs Status": DusStatusPage(driver, version),
                                   "Cells Status": CellsStatusPage(driver, version),
                                   "VMs Status": VMsStatusPage(driver, version),
                                   "X2 Links Status": X2LinksStatusStatusPage(driver, version),
                                   "CU Properties": CUPropertiesStatusStatusPage(driver, version)}
        super(BtsStatus, self).__init__(driver, version, self._instance_dict)


class DusStatusPage(object):
    """
    As a class will be called by BtsStatus, all operations on DUs Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'DUs Status']

    def __init__(self, driver, version):
        self._navigation_panel = DusStatusPageNavigationPanel(driver, version)
        self._view_panel = DusStatusPageViewPanel(driver, version)

    def get_VMs_status_info(self, timeout=60):
        """
        Method for getting DUs status

        :param timeout: int, timeout for getting the status info

        :return: dict, specific information of DUs
        """
        return self._view_panel.get_VMs_status_info(timeout=timeout)

    def get_dus_status_info(self, get_info, cell_id, timeout=60):
        """
        Method for getting DUs status

        :param get_info: str, status info details
        :param cell_id: str, cell id for corresponding to status info
        :param timeout: int, timeout for getting the status info

        :return: dict, specific information of DUs
        """
        return self._view_panel.get_cell_info(get_info=get_info, cell_id=cell_id, timeout=timeout)


class DusStatusPageNavigationPanel(NavigationPanel):
    pass


class DusStatusPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        super(DusStatusPageViewPanel, self).__init__(driver, version)

    def get_cell_status_info(self, cell_id, hover_xpath, timeout):
        """
        Method for getting Radio Modules Status after mouse hovering on the Radio Module

        :param cell_id: str, cell id for corresponding to status info
        :param hover_xpath: str, hovering xpath of the cell
        :param timeout: int, timeout for the element be available to click

        :return: dict, specific information of DUs or Cells or VMs accordingly
        """
        status_info = []
        for i in cell_id:
            self.wait_for_visibility(hover_xpath.format(i), timeout)
            self.perform_element_hover(hover_xpath.format(i), timeout)
            status_info.append(self._parse_status_info())
        return status_info

    def _parse_status_info(self):
        """
        This keyword is for getting all the details of status related cell info from tool tip and parse it in to dict

        :return: dict of information collected for status module
        """
        modules_status = {}
        for item in self.get_text_from_all_matching_elements(self.locator.DU_MODULE_STATUS_INFO_XPATH):
            modules_status.update({item.split(":")[0].strip(): item.split(":")[-1].strip()})
        return modules_status

    def get_cell_info(self, get_info, cell_id, timeout=60):
        info_mapping = {
            'Cells': self.locator.CELL_ID_XPATH,
            'DUs': self.locator.DU_CELL_ID_XPATH,
            'X2_Links_Status': self.locator.X2_LINK_ID_XPATH,
            'NG_Links_Status': self.locator.X2_LINK_ID_XPATH
        }
        detail_panel_info_xpath = info_mapping.get(get_info, self.locator.X2_LINK_ID_XPATH)
        return self.get_cell_status_info(cell_id=cell_id, hover_xpath=detail_panel_info_xpath,
                                         timeout=timeout)

    def _get_DUs_info(self, row_xpath, status_info_xpath, status_info_row, timeout=60):
        """
        This keyword is for getting all the details from table view

        :param row_xpath: str, xpath for the row view
        :param status_info_xpath: str, xpath for the status view
        :param status_info_row: str, xpath for the status row view
        :param timeout: int, timeout for the element be available to click

        :return: list of dict, every dict info in one line from the table view and module view
        """
        param_error_list = []
        key_list = self.get_fields_info_from_row(self.locator.TABLE_XPATH, timeout)
        self.wait_for_visibility((By.XPATH, row_xpath))
        param_info = len(self._driver.find_elements_by_xpath(row_xpath))
        for index in range(1, param_info + 1):
            self.wait_for_visibility((By.XPATH, status_info_xpath.format(index)))
            severity = self._driver.find_element_by_xpath(status_info_xpath.format(index)).get_attribute("title")
            dist_name_info_xpath = status_info_row.format(index)
            value_list = self.get_fields_info_from_row(dist_name_info_xpath, timeout)
            value_list.insert(0, severity)
            del value_list[1]
            param_error_list.append(dict(zip(key_list, value_list)))
        logging.debug("printing param error list info={}".format(param_error_list))
        return param_error_list

    def get_VMs_status_info(self, timeout=60):
        """
        Method for getting VMs status after clicking table view

        :param timeout: int, timeout for getting the status info

        :return: dict, specific information of DUs or Cells or VMs or X2 links accordingly
        """
        if self.element_exists(self.locator.DU_TABLE_XPATH):
            self.wait_for_visibility(self.locator.DU_TABLE_XPATH, timeout)
            self.click_enabled_element(self.locator.DU_TABLE_XPATH, timeout)
        else:
            logging.info("Table view button is already clicked")
        return self._get_DUs_info(row_xpath=self.locator.VM_STAUS_ROW_XPATH,
                                  status_info_xpath=self.locator.VM_STATUS_XPATH,
                                  status_info_row=self.locator.VM_STATUS_INFO_ROW_XPATH)


class CellsStatusPage(object):
    """
    As a class will be called by BtsStatus, all operations on Cells Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'Cells Status']

    def __init__(self, driver, version):
        self._navigation_panel = DusStatusPageNavigationPanel(driver, version)
        self._view_panel = DusStatusPageViewPanel(driver, version)
        self.common_actions = {
            'get_dus_status_info':
                self._view_panel.get_cell_info
        }
        self.__dict__.update(self.common_actions)


