class CUPropertiesStatusStatusPage(object):
    """
    As a class will be called by BtsStatus, all operations on CU Properties page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'CU Properties']

    def __init__(self, driver, version):
        self._navigation_panel = DusStatusPageNavigationPanel(driver, version)
        self._view_panel = CUPropertiesPageViewPanel(driver, version)

    def get_cu_properties_status_info(self, timeout=60):
        """
        Method for getting CU properties information
        :param timeout: int, timeout for getting the status info

        :return: dict, Dictionary of the CU Properties
        """
        return self._view_panel.get_cu_properties_status_info(timeout)


class CUPropertiesPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        super(CUPropertiesPageViewPanel, self).__init__(driver, version)

    def get_cu_properties_status_info(self, timeout=60):
        """
         Method for getting cu properties status info in a dict format
         :param timeout: int, timeout for getting the status info

        :return: dict, Dictionary of the cu properties
        """
        self.click_enabled_element(self.locator.CU_STATUS_BUTTON, timeout)
        cu_properties_info = self.get_text(self.locator.CU_STATUS_PAGE)
        list_info = cu_properties_info.splitlines()
        res_dct = {list_info[i].replace(':', ''): list_info[i + 1] for i in range(1, len(list_info), 2)}
        res_dct[list_info[0].split('-')[0] + ' ID'] = list_info[0].split('-')[1].strip()
        return res_dct
